interface TaskGridProps {
  tasks: Task[];
  theme: any;
  rowHeight: number;
  availableUsers?: Array<{ id: string; name: string; initials: string; color: string }>;
  templates: Required<GanttTemplates>; // v0.8.0
  onTaskClick?: (task: Task) => void;
  /** v1.9.16: la seleccion sale del Gantt — ver `onTaskSelectionChange` en types.ts */
  onTaskSelectionChange?: (taskId: string | null) => void;
  /** v1.9.17: ...y tambien entra — ver `selectedTaskId` en types.ts */
  selectedTaskId?: string | null;
  onTaskDblClick?: (task: Task) => void; // v0.8.0
  onTaskContextMenu?: (task: Task, event: React.MouseEvent) => void; // v0.8.0
  onTaskToggle?: (taskId: string) => void;
  scrollTop: number;
  columns: GanttColumn[];
  onToggleColumn: (columnType: ColumnType) => void;
  onColumnResize?: (columnId: ColumnType, newWidth: number) => void; // v0.13.8
  onTaskUpdate?: (taskId: string, updates: Partial<Task>) => void;
  // Drag-fill: apply a value to many tasks at once (assignees/start/end date).
  onBulkFill?: (
    taskIds: string[],
    column: 'assignees' | 'startDate' | 'endDate',
    value: any,
  ) => void;

  // Hierarchy handlers
  onTaskIndent?: (taskIds: string[]) => void;
  onTaskOutdent?: (taskIds: string[]) => void;
  onTaskMove?: (taskIds: string[], direction: 'up' | 'down') => void;
  onMultiTaskDelete?: (taskIds: string[]) => void;
  onTaskDuplicate?: (taskIds: string[]) => void;
  onTaskCreate?: (afterTaskId: string, direction: 'above' | 'below') => void;
  onTaskRename?: (taskId: string, newName: string) => void;
  /** La tarea recién insertada: su nombre se abre solo y, si se deja vacío, `onTareaNombrada(id, null)` la quita. */
  tareaPorNombrar?: string | null;
  /** { 'AAAA-MM-DD': 'Nombre' }: los festivos del espacio, marcados en el calendario de Inicio/Fin. */
  festivos?: Readonly<Record<string, string>>;
  onTareaNombrada?: (taskId: string, nombre: string | null) => void;
  /** 1.9.45 · fila «+ Add task» al final de la rejilla (la app decide qué hace). */
  addTaskRow?: { label: string; onClick: () => void };
  onCreateSubtask?: (parentTaskId: string) => void;
  /** 1.9.47 · QA Asakaa E14: «Dependencias…» en el menú contextual. */
  onTaskDependencies?: (task: Task) => void;
  onOpenTaskModal?: (task: Task) => void;
  // v0.17.34: Delete confirmation request (shows modal instead of deleting directly)
  /** v1.9.6: ahora recibe TODOS los ids a borrar (bulk desde el menú contextual
   *  con multi-selección) + una etiqueta para el modal de confirmación. */
  onDeleteRequest?: (taskIds: string[], label: string) => void;
  // v0.17.68: Reparent task via drag & drop
  onTaskReparent?: (taskId: string, newParentId: string | null, position?: number) => void;
  /** v1.9.10: árbol COMPLETO sin filtrar. Cuando hay un filtro activo, `tasks`
   *  es un subconjunto; para reordenar correctamente la posición de destino debe
   *  traducirse al índice real entre TODOS los hermanos (no solo los visibles). */
  allTasks?: Task[];
  // v0.18.15: Scroll container ref for auto-scroll during drag
  scrollContainerRef?: React.RefObject<HTMLElement>;
  // v5.1.0: CPM visual state
  showCriticalPath?: boolean;
  /** Gantt v6 (Asakaa): la tabla de la maqueta — Tarea · Resp. · Inicio · Fin · %, cabecera de 60 px. */
  v6?: boolean;
  /** G15 · Alt+←/→: mover la tarea N días hábiles. */
  onMoverDias?: (task: Task, dias: number) => void;
  /** A12 · editar en la celda. */
  puedeEditarEnTabla?: (task: Task) => boolean;
  onDuracionEnTabla?: (task: Task, dias: number) => void;
  onProgresoEnTabla?: (task: Task, avance: number) => void;
  /** A14 · las columnas del «+». */
  columnasV6?: { elegidas: ColumnType[]; alternar: (id: ColumnType) => void; contexto: ContextoDeColumnas; verCostos: boolean; hayLineaBase: boolean };
  /** Gantt v6: «13 tareas · completadas ocultas», encima de los títulos. */
  resumenV6?: string;
  /** Gantt v6: el botón «contraer todos los grupos». */
  onContraerTodo?: () => void;
  /** Gantt ronda 2 · P2 · «Mostrar» las completadas ocultas, junto a su contador. */
  onMostrarOcultas?: () => void;
  /** G14 · tras «Mostrar», la acción para volver a ocultar */
  onOcultarCompletadas?: () => void;
  /** Gantt ronda 2 · R1 · las filas que se dibujan; `null`, todas. */
  filasVisibles?: { desde: number; hasta: number } | null;
  /** Gantt ronda 2 · R4 · «12 vencidas» y su «Ver» (activa el filtro «Solo vencidas»). */
  avisoVencidas?: string;
  onVerVencidas?: () => void;
}

/** A12 · un número que se edita en su celda: clic o Enter para escribir, Enter o salir guarda, Escape deja como estaba. */
function CeldaNumericaV6({ valor, sufijo, min, max, derecha, etiqueta, alGuardar }: {
  valor: number; sufijo: string; min: number; max: number; derecha?: boolean; etiqueta: string; alGuardar: (n: number) => void;
}) {
  const [texto, setTexto] = useState<string | null>(null);
  const guardar = () => {
    const n = Number(texto);
    setTexto(null);
    if (texto !== null && texto.trim() !== '' && Number.isFinite(n) && n !== valor) alGuardar(Math.min(max, Math.max(min, Math.round(n))));
  };
  const estilo: React.CSSProperties = { width: '100%', textAlign: derecha ? 'right' : 'left', fontFamily: "'JetBrains Mono', ui-monospace, monospace", fontVariantNumeric: 'tabular-nums', fontSize: 12, color: 'var(--v6-texto-2, #4D5761)' };
  if (texto === null) {
    return (
      <button type="button" data-celda-editable aria-label={`${etiqueta}: ${valor} ${sufijo}`} onClick={(e) => { e.stopPropagation(); setTexto(String(valor)); }}
        style={{ ...estilo, background: 'transparent', border: 0, padding: 0, cursor: 'text' }}>
        {sufijo === '%' ? `${valor}%` : `${valor} ${sufijo}`}
      </button>
    );
  }
  return (
    <input autoFocus type="number" min={min} max={max} value={texto} aria-label={etiqueta}
      onClick={(e) => e.stopPropagation()}
      onFocus={(e) => e.currentTarget.select()}
      onChange={(e) => setTexto(e.target.value)}
      onBlur={guardar}
      onKeyDown={(e) => {
        e.stopPropagation();
        if (e.key === 'Enter') { e.preventDefault(); e.currentTarget.blur(); }
        if (e.key === 'Escape') setTexto(null);
      }}
      style={{ ...estilo, height: 24, boxSizing: 'border-box', padding: '0 4px', borderRadius: 6, border: '1px solid var(--v6-acento, #0FA392)', background: 'var(--v6-tarjeta, #fff)', outline: 'none' }} />
  );
}

export function TaskGrid({
  tasks,
  theme,
  rowHeight: ROW_HEIGHT,
  availableUsers = [],
  templates: _templates, // TODO: Use templates for custom rendering
  onTaskClick,
  onTaskSelectionChange,
  selectedTaskId,
  onTaskDblClick, // v0.8.0
  onTaskContextMenu, // v0.8.0
  onTaskToggle,
  scrollTop: _scrollTop,
  columns,
  onToggleColumn,
  onColumnResize,
  onTaskUpdate,
  onBulkFill,
  onTaskIndent,
  onTaskOutdent,
  onTaskMove,
  onMultiTaskDelete,
  onTaskDuplicate,
  onTaskCreate,
  onTaskRename,
  tareaPorNombrar,
  onTareaNombrada,
  festivos,
  addTaskRow,
  onCreateSubtask,
  onTaskDependencies,
  onOpenTaskModal,
  onDeleteRequest, // v0.17.34
  onTaskReparent, // v0.17.68
  allTasks, // v1.9.10: árbol completo para traducir posición con filtros activos
  scrollContainerRef, // v0.18.15
  showCriticalPath = false, // v5.1.0
  v6 = false,
  onMoverDias,
  columnasV6,
  puedeEditarEnTabla = () => true,
  onDuracionEnTabla,
  onProgresoEnTabla,
  resumenV6,
  onContraerTodo,
  onMostrarOcultas,
  onOcultarCompletadas,
  filasVisibles = null,
  avisoVencidas,
  onVerVencidas,
}: TaskGridProps) {
  const esGrid = useGanttEnEspanol(); // QA Asakaa 2.1
  // v0.16.2: Get translations from context
  const translations = useContext(GanttI18nContext);

  const [hoveredTaskId, setHoveredTaskId] = useState<string | null>(null);
  const [editingTaskId, setEditingTaskId] = useState<string | null>(null);
  const [editingTaskName, setEditingTaskName] = useState('');
  const editInputRef = useRef<HTMLInputElement>(null);

  // v0.13.8: Column resize state
  const [resizingColumn, setResizingColumn] = useState<ColumnType | null>(null);
  const [resizeStartX, setResizeStartX] = useState(0);
  const [resizeStartWidth, setResizeStartWidth] = useState(0);
  const [contextMenu, setContextMenu] = useState<{
    isOpen: boolean;
    x: number;
    y: number;
    type: 'header' | 'task';
    columnId?: ColumnType;
    task?: Task;
  }>({
    isOpen: false,
    x: 0,
    y: 0,
    type: 'header',
  });

  // v0.17.68: Drag & drop state for reparenting tasks
  const [draggedTaskId, setDraggedTaskId] = useState<string | null>(null);
  const [dropTargetTaskId, setDropTargetTaskId] = useState<string | null>(null);
  const [dropPosition, setDropPosition] = useState<'above' | 'below' | 'child' | null>(null);
  const dragStartY = useRef<number>(0);
  const dragThreshold = 5; // Minimum pixels to move before drag starts
  const isDraggingRef = useRef<boolean>(false);
  // v0.17.146: Ghost position for drag preview + isDragging state for re-render
  const [ghostPosition, setGhostPosition] = useState<{ x: number; y: number } | null>(null);
  const [isDraggingState, setIsDraggingState] = useState(false);
  // v0.18.15: Auto-scroll during drag
  const autoScrollRAF = useRef<number | null>(null);

  // Drag-fill (Excel-style): drag a value from one cell down across rows to
  // apply it to all covered tasks at once. Supported for assignees + dates.
  const [fillDrag, setFillDrag] = useState<{
    sourceTaskId: string;
    column: 'assignees' | 'startDate' | 'endDate';
    sourceIndex: number;   // index in flatTasks of the source row
    targetIndex: number;   // index of the last row currently covered
  } | null>(null);

  // v0.17.132: Date picker state for column cells
  const [datePickerState, setDatePickerState] = useState<{
    taskId: string;
    field: 'startDate' | 'endDate';
    month: Date;
    position: { top: number; left: number };
  } | null>(null);

  // v0.17.215: Keyboard shortcuts with sticky positioning - always visible
  const [showKeyboardHelp, setShowKeyboardHelp] = useState(false);
  const keyboardHelpRef = useRef<HTMLDivElement>(null);

  // v0.17.215: Close keyboard help when clicking outside
  useEffect(() => {
    function handleClickOutside(event: MouseEvent) {
      if (keyboardHelpRef.current && !keyboardHelpRef.current.contains(event.target as Node)) {
        setShowKeyboardHelp(false);
      }
    }
    if (showKeyboardHelp) {
      document.addEventListener('mousedown', handleClickOutside);
      return () => document.removeEventListener('mousedown', handleClickOutside);
    }
    return undefined;
  }, [showKeyboardHelp]);

  // Focus input when editing starts
  useEffect(() => {
    if (editingTaskId && editInputRef.current) {
      editInputRef.current.focus();
      editInputRef.current.select();
    }
  }, [editingTaskId]);

  // v0.13.8: Handle column resize mouse events
  useEffect(() => {
    if (!resizingColumn) return;

    const handleMouseMove = (e: MouseEvent) => {
      const deltaX = e.clientX - resizeStartX;
      const newWidth = resizeStartWidth + deltaX;
      onColumnResize?.(resizingColumn, newWidth);
    };

    const handleMouseUp = () => {
      setResizingColumn(null);
      document.body.style.cursor = '';
      document.body.style.userSelect = '';
    };

    document.addEventListener('mousemove', handleMouseMove);
    document.addEventListener('mouseup', handleMouseUp);
    document.body.style.cursor = 'col-resize';
    document.body.style.userSelect = 'none';

    return () => {
      document.removeEventListener('mousemove', handleMouseMove);
      document.removeEventListener('mouseup', handleMouseUp);
      document.body.style.cursor = '';
      document.body.style.userSelect = '';
    };
  }, [resizingColumn, resizeStartX, resizeStartWidth, onColumnResize]);

  // Multi-selection hook
  const {
    selectedTaskIds,
    handleTaskClick: handleSelectionClick,
    isTaskSelected,
  } = useGanttSelection(selectedTaskId);

  /* G15 · el foco sigue a la selección con teclado: la tarea puede estar fuera de la franja que se pinta. */
  const filaPorEnfocar = useRef<string | null>(null);

  // Keyboard shortcuts hook
  const { setIsEditing } = useGanttKeyboard({
    tasks,
    selectedTaskIds,
    onTaskSelect: (taskId: string, multiSelect?: boolean) => {
      const flatTasks = flattenTasksUtil(tasks);
      const flatTaskIds = flatTasks.map(t => t.id);
      handleSelectionClick(taskId, flatTaskIds, multiSelect || false, false);
      filaPorEnfocar.current = taskId;
      /*
       * SE AVISA HACIA FUERA. Antes esta seleccion moria aqui dentro: quien
       * montara el Gantt no tenia forma de seguir el resaltado, y el SaaS
       * acabo con su propio recorrido en paralelo que se desincronizaba.
       *
       * En seleccion multiple (Shift) se manda la tarea a la que se acaba de
       * llegar, que es la que el usuario esta mirando.
       */
      onTaskSelectionChange?.(taskId);
    },
    onTaskCreate: onTaskCreate || (() => {}),
    onTaskDelete: onMultiTaskDelete || (() => {}),
    onTaskDuplicate: onTaskDuplicate || (() => {}),
    onTaskMove: onTaskMove || (() => {}),
    onTaskIndent: onTaskIndent || (() => {}),
    onTaskOutdent: onTaskOutdent || (() => {}),
    onTaskRename: (taskId: string) => {
      // Start inline rename when F2 is pressed
      const task = flattenTasksUtil(tasks).find(t => t.id === taskId);
      if (task) {
        handleRenameStart(task);
      }
    },
    onTaskToggleExpand: onTaskToggle || (() => {}),
    onOpenTaskModal: (taskId: string) => {
      const task = flattenTasksUtil(tasks).find(t => t.id === taskId);
      if (task && onOpenTaskModal) {
        onOpenTaskModal(task);
      }
    },
    enableKeyboard: true,
    v6: v6 ? { abrirPanel: (t: Task) => onTaskClick?.(t), moverDias: onMoverDias } : undefined,
  });

  const flattenTasks = (tasks: Task[], level = 0, parentWbs = ''): Array<{ task: Task; level: number }> => {
    const result: Array<{ task: Task; level: number }> = [];

    // Sort by position to maintain creation order
    const sortedTasks = [...tasks].sort((a, b) => (a.position ?? 0) - (b.position ?? 0));
    for (let i = 0; i < sortedTasks.length; i++) {
      const task = sortedTasks[i]!;
      // v1.5.93: Honor a pre-stamped wbsCode (set by GanttBoard.tasksWithStableWbs
      // BEFORE filtering) so visible numbers stay stable when the user filters.
      // Fallback to local sequence when none was provided.
      const seq = i + 1;
      const localWbs = parentWbs
        ? `${parentWbs}.${seq}`         // Child: "1.1", "1.1.1"
        : `${seq}.0`;                    // Root: "1.0", "2.0"
      const wbsCode = task.wbsCode || localWbs;
      task.wbsCode = wbsCode;
      result.push({ task, level });
      if (task.subtasks && task.subtasks.length > 0 && task.isExpanded) {
        // Strip a trailing ".0" from a stamped root WBS so children build "4.1" not "4.0.1"
        const stampedChildPrefix = task.wbsCode?.replace(/\.0$/, '');
        const childPrefix = stampedChildPrefix
          || (parentWbs ? `${parentWbs}.${seq}` : `${seq}`);
        result.push(...flattenTasks(task.subtasks, level + 1, childPrefix));
      }
    }

    return result;
  };

  const flatTasks = flattenTasks(tasks);
  /* G15 · un solo punto de Tab en toda la tabla: la seleccionada si se pinta; si no, la primera que se pinta. */
  const filaConTab = (() => {
    const desde = filasVisibles?.desde ?? 0;
    const hasta = filasVisibles?.hasta ?? flatTasks.length - 1;
    for (let i = desde; i <= hasta; i++) if (flatTasks[i] && isTaskSelected(flatTasks[i]!.task.id)) return flatTasks[i]!.task.id;
    return flatTasks[desde]?.task.id;
  })();
  useEffect(() => {
    const id = filaPorEnfocar.current;
    if (!id) return;
    filaPorEnfocar.current = null;
    const indice = flatTasks.findIndex((f) => f.task.id === id);
    const c = scrollContainerRef?.current;
    if (indice < 0) return;
    if (c) {
      const arriba = indice * ROW_HEIGHT;
      const alto = c.clientHeight - HEADER_HEIGHT;
      if (arriba < c.scrollTop) c.scrollTop = arriba;
      else if (arriba + ROW_HEIGHT > c.scrollTop + alto) c.scrollTop = arriba + ROW_HEIGHT - alto;
    }
    let intentos = 0;
    const enfocar = () => {
      const el = document.querySelector<HTMLElement>(`[data-task-row="${CSS.escape(id)}"]`);
      if (el) el.focus({ preventScroll: true });
      else if (intentos++ < 6) requestAnimationFrame(enfocar);
    };
    enfocar();
  });
  const HEADER_HEIGHT = v6 ? 60 : 48; // Gantt v6: 24 (resumen) + 36 (títulos); Timeline igual

  // v0.17.221: Calculate content height to match Timeline exactly
  // This ensures proper scroll sync without content cutoff
  const contentHeight = Math.max(flatTasks.length * ROW_HEIGHT, 600 - HEADER_HEIGHT);

  // ── Drag-fill (Excel-style fill handle) ─────────────────────────────────
  // Reads the source cell's value and applies it to every task between the
  // source row and the row under the cursor (inclusive). Parent tasks are
  // skipped (their assignees/dates are read-only / auto-calculated).
  const getFillValue = (task: Task, column: 'assignees' | 'startDate' | 'endDate') => {
    if (column === 'assignees') return task.assignees;
    if (column === 'startDate') return task.startDate;
    return task.endDate;
  };

  const handleFillDragStart = (
    e: React.MouseEvent,
    sourceTaskId: string,
    column: 'assignees' | 'startDate' | 'endDate',
    sourceIndex: number,
  ) => {
    e.preventDefault();
    e.stopPropagation();
    setFillDrag({ sourceTaskId, column, sourceIndex, targetIndex: sourceIndex });

    // v1.9.7: cursor global durante el arrastre — sin esto el cursor "parpadea"
    // o desaparece al pasar sobre celdas con estilos de cursor propios.
    document.body.style.cursor = 'crosshair';
    document.body.style.userSelect = 'none';

    // Measure the grid body's top edge in viewport coords. The rows are laid
    // out at fixed ROW_HEIGHT starting from this top, so the row index under
    // the cursor = floor((cursorY - bodyTop) / ROW_HEIGHT).
    const bodyEl = (e.currentTarget as HTMLElement).closest('[data-grid-body]') as HTMLElement | null;

    const rowIndexAt = (clientY: number): number => {
      const top = bodyEl?.getBoundingClientRect().top ?? 0;
      let idx = Math.floor((clientY - top) / ROW_HEIGHT);
      idx = Math.max(0, Math.min(flatTasks.length - 1, idx));
      if (idx < sourceIndex) idx = sourceIndex; // fill downward only
      return idx;
    };

    // v1.9.7: auto-scroll cerca de los bordes del contenedor (mismo patrón que
    // el drag de reordenar, v0.18.15). Sin esto, en proyectos grandes el
    // relleno se detiene en la última fila visible y no se puede seguir
    // arrastrando hacia abajo. El loop RAF también actualiza targetIndex
    // mientras desplaza (no llegan mousemove si el mouse está quieto).
    let lastClientY = e.clientY;
    const container = scrollContainerRef?.current ?? null;

    const stopAutoScroll = () => {
      if (autoScrollRAF.current) {
        cancelAnimationFrame(autoScrollRAF.current);
        autoScrollRAF.current = null;
      }
    };

    const updateTarget = () => {
      const idx = rowIndexAt(lastClientY);
      setFillDrag(prev => (prev ? { ...prev, targetIndex: idx } : prev));
    };

    const maybeAutoScroll = () => {
      stopAutoScroll();
      if (!container) return;
      const rect = container.getBoundingClientRect();
      const edgeZone = 60;
      const maxSpeed = 12;
      const distFromTop = lastClientY - rect.top;
      const distFromBottom = rect.bottom - lastClientY;

      if (distFromBottom < edgeZone && container.scrollTop < container.scrollHeight - container.clientHeight) {
        const speed = Math.max(1, Math.round(maxSpeed * (1 - Math.max(0, distFromBottom) / edgeZone)));
        const scroll = () => {
          container.scrollTop += speed;
          updateTarget();
          if (container.scrollTop < container.scrollHeight - container.clientHeight) {
            autoScrollRAF.current = requestAnimationFrame(scroll);
          }
        };
        autoScrollRAF.current = requestAnimationFrame(scroll);
      } else if (distFromTop < edgeZone && container.scrollTop > 0) {
        const speed = Math.max(1, Math.round(maxSpeed * (1 - Math.max(0, distFromTop) / edgeZone)));
        const scroll = () => {
          container.scrollTop -= speed;
          updateTarget();
          if (container.scrollTop > 0) {
            autoScrollRAF.current = requestAnimationFrame(scroll);
          }
        };
        autoScrollRAF.current = requestAnimationFrame(scroll);
      }
    };

    const onMove = (ev: MouseEvent) => {
      lastClientY = ev.clientY;
      updateTarget();
      maybeAutoScroll();
    };

    const onUp = (ev: MouseEvent) => {
      window.removeEventListener('mousemove', onMove);
      window.removeEventListener('mouseup', onUp);
      stopAutoScroll();
      document.body.style.cursor = '';
      document.body.style.userSelect = '';
      setFillDrag(null);

      // Compute the target index directly from the final cursor position so we
      // don't depend on async state having flushed.
      const targetIndex = rowIndexAt(ev.clientY);
      const src = flatTasks.find(ft => ft.task.id === sourceTaskId)?.task;
      if (!src) return;
      const value = getFillValue(src, column);
      const from = Math.min(sourceIndex, targetIndex);
      const to = Math.max(sourceIndex, targetIndex);

      // Collect the target task ids (skip the source + parent rows).
      const targetIds: string[] = [];
      for (let i = from; i <= to; i++) {
        if (i === sourceIndex) continue;
        const target = flatTasks[i]?.task;
        if (!target) continue;
        const isParent = !!(target.subtasks && target.subtasks.length > 0);
        if (isParent) continue; // parents are read-only for assignees/dates
        targetIds.push(target.id);
      }
      if (targetIds.length === 0) return;

      // Single dedicated callback (like onTaskReparent/onTaskMove) — the
      // consumer applies the value to all targets and persists them. This is
      // far more reliable than firing onTaskUpdate N times and hoping the
      // batched state + onTasksChange diff picks them all up.
      onBulkFill?.(targetIds, column, value);
    };

    window.addEventListener('mousemove', onMove);
    window.addEventListener('mouseup', onUp);
  };

  // True if this row index is inside the current fill-drag range (for preview).
  const isInFillRange = (index: number) => {
    if (!fillDrag) return false;
    const from = Math.min(fillDrag.sourceIndex, fillDrag.targetIndex);
    const to = Math.max(fillDrag.sourceIndex, fillDrag.targetIndex);
    return index >= from && index <= to;
  };

  // Calculate duration
  const getDuration = (task: Task) => {
    if (!task.startDate || !task.endDate) return '-';
    const days = Math.ceil((task.endDate.getTime() - task.startDate.getTime()) / (1000 * 60 * 60 * 24));
    return `${days}d`;
  };

  /* La tarea recién insertada entra con su nombre abierto y vacío. */
  useEffect(() => {
    if (!tareaPorNombrar || editingTaskId === tareaPorNombrar) return;
    if (!flattenTasksUtil(tasks).some(t => t.id === tareaPorNombrar)) return;
    setEditingTaskId(tareaPorNombrar);
    setEditingTaskName('');
    setIsEditing(true);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [tareaPorNombrar, tasks]);

  // Handle rename start
  const handleRenameStart = (task: Task) => {
    setEditingTaskId(task.id);
    setEditingTaskName(task.name);
    setIsEditing(true);
  };

  // Handle rename save
  /** Devuelve true si era la recién insertada (su nombre va por onTareaNombrada). */
  const handleRenameSave = (taskId: string): boolean => {
    if (taskId === tareaPorNombrar && onTareaNombrada) {
      const nombre = editingTaskName.trim();
      setEditingTaskId(null);
      setEditingTaskName('');
      setIsEditing(false);
      onTareaNombrada(taskId, nombre || null);
      return true;
    }
    if (editingTaskName.trim() && editingTaskName !== tasks.find(t => t.id === taskId)?.name) {
      onTaskRename?.(taskId, editingTaskName.trim());
    }
    setEditingTaskId(null);
    setEditingTaskName('');
    setIsEditing(false);
    return false;
  };

  // Handle rename cancel
  const handleRenameCancel = () => {
    /* Escape en la recién insertada: se quita (nunca se guardó) */
    if (editingTaskId && editingTaskId === tareaPorNombrar && onTareaNombrada) onTareaNombrada(editingTaskId, null);
    setEditingTaskId(null);
    setEditingTaskName('');
    setIsEditing(false);
  };

  // Handle create subtask
  const handleCreateSubtaskClick = (task: Task, e: React.MouseEvent) => {
    e.stopPropagation();
    // Create subtask at the end of parent's children
    onCreateSubtask?.(task.id);
  };

  // v0.17.68: Drag handlers for reparenting
  const handleDragStart = (taskId: string, e: React.MouseEvent) => {
    // Only start drag from the drag handle area
    e.preventDefault();
    dragStartY.current = e.clientY;
    setDraggedTaskId(taskId);
    isDraggingRef.current = false;
    setIsDraggingState(false);
    // v0.17.146: Initialize ghost position
    setGhostPosition({ x: e.clientX, y: e.clientY });
  };

  const handleDragMove = (e: MouseEvent) => {
    if (!draggedTaskId) return;

    const deltaY = Math.abs(e.clientY - dragStartY.current);
    if (deltaY > dragThreshold && !isDraggingRef.current) {
      isDraggingRef.current = true;
      setIsDraggingState(true);
    }

    // v0.17.146: Update ghost position
    setGhostPosition({ x: e.clientX, y: e.clientY });

    if (!isDraggingRef.current) return;

    // v0.18.15: Auto-scroll when dragging near edges of scroll container
    if (scrollContainerRef?.current) {
      const container = scrollContainerRef.current;
      const rect = container.getBoundingClientRect();
      const edgeZone = 60; // px from edge to start scrolling
      const maxSpeed = 12; // max px per frame

      if (autoScrollRAF.current) {
        cancelAnimationFrame(autoScrollRAF.current);
        autoScrollRAF.current = null;
      }

      const distFromTop = e.clientY - rect.top;
      const distFromBottom = rect.bottom - e.clientY;

      if (distFromTop < edgeZone && container.scrollTop > 0) {
        // Scroll up — speed increases as mouse gets closer to edge
        const speed = Math.round(maxSpeed * (1 - distFromTop / edgeZone));
        const scroll = () => {
          container.scrollTop -= speed;
          if (isDraggingRef.current && container.scrollTop > 0) {
            autoScrollRAF.current = requestAnimationFrame(scroll);
          }
        };
        autoScrollRAF.current = requestAnimationFrame(scroll);
      } else if (distFromBottom < edgeZone && container.scrollTop < container.scrollHeight - container.clientHeight) {
        // Scroll down
        const speed = Math.round(maxSpeed * (1 - distFromBottom / edgeZone));
        const scroll = () => {
          container.scrollTop += speed;
          if (isDraggingRef.current && container.scrollTop < container.scrollHeight - container.clientHeight) {
            autoScrollRAF.current = requestAnimationFrame(scroll);
          }
        };
        autoScrollRAF.current = requestAnimationFrame(scroll);
      }
    }

    // Find which task we're hovering over
    const rows = document.querySelectorAll('[data-task-row]');
    let foundTarget: string | null = null;
    let position: 'above' | 'below' | 'child' | null = null;

    rows.forEach((row) => {
      const rect = row.getBoundingClientRect();
      const taskId = row.getAttribute('data-task-row');

      if (taskId && taskId !== draggedTaskId && e.clientY >= rect.top && e.clientY <= rect.bottom) {
        foundTarget = taskId;

        // Determine drop position based on Y position within the row
        const relativeY = e.clientY - rect.top;
        const rowHeight = rect.height;

        if (relativeY < rowHeight * 0.25) {
          position = 'above';
        } else if (relativeY > rowHeight * 0.75) {
          position = 'below';
        } else {
          // Middle zone = make it a child
          position = 'child';
        }
      }
    });

    setDropTargetTaskId(foundTarget);
    setDropPosition(position);
  };

  const handleDragEnd = () => {
    if (isDraggingRef.current && draggedTaskId && dropTargetTaskId && dropPosition) {
      // Determine the new parent and position
      if (dropPosition === 'child') {
        // Make it a child of the target task
        onTaskReparent?.(draggedTaskId, dropTargetTaskId);
      } else if (dropPosition === 'above' || dropPosition === 'below') {
        // Find the parent of the target task
        const findParent = (taskList: Task[], targetId: string, parent: string | null = null): string | null => {
          for (const t of taskList) {
            if (t.id === targetId) return parent;
            if (t.subtasks) {
              const found = findParent(t.subtasks, targetId, t.id);
              if (found !== undefined) return found;
            }
          }
          return undefined as unknown as string | null;
        };

        // v1.9.10: para traducir la posición correctamente cuando hay un filtro
        // activo, usamos el árbol COMPLETO (allTasks) si está disponible; si no,
        // caemos a `tasks` (comportamiento previo, sin filtro). El target/parent
        // se buscan también en el árbol elegido.
        const tree = allTasks && allTasks.length > 0 ? allTasks : tasks;

        // Find the parent of the dragged task (to know if it's in the same sibling group)
        const draggedParent = findParent(tree, draggedTaskId, null);
        const targetParent = findParent(tree, dropTargetTaskId, null);

        // v0.18.13: Compute position accounting for the dragged task being removed first.
        // reparentTask() removes the task then inserts — if the dragged task is before the
        // target in the SAME sibling group, all subsequent indices shift down by 1.
        // v1.9.10: `siblings` son los hermanos del ÁRBOL COMPLETO → el índice es la
        // posición real en BD, aunque la vista esté filtrada.
        const computePosition = (siblings: Task[], targetId: string, dragId: string, sameGroup: boolean): number => {
          const targetIdx = siblings.findIndex(t => t.id === targetId);
          const dragIdx = sameGroup ? siblings.findIndex(t => t.id === dragId) : -1;
          let pos = dropPosition === 'below' ? targetIdx + 1 : targetIdx;
          // If dragged task is before the target in the same group, removing it shifts indices down
          if (sameGroup && dragIdx !== -1 && dragIdx < targetIdx) {
            pos -= 1;
          }
          return Math.max(0, pos);
        };

        if (targetParent === null) {
          // Target is at root level
          const sameGroup = draggedParent === null; // dragged is also at root
          const pos = computePosition(tree, dropTargetTaskId, draggedTaskId, sameGroup);
          onTaskReparent?.(draggedTaskId, null, pos);
        } else {
          // Target has a parent
          const parentTask = findTaskInTree(tree, targetParent);
          if (parentTask?.subtasks) {
            const sameGroup = draggedParent === targetParent; // same parent
            const pos = computePosition(parentTask.subtasks, dropTargetTaskId, draggedTaskId, sameGroup);
            onTaskReparent?.(draggedTaskId, targetParent, pos);
          }
        }
      }
    }

    // Reset drag state
    if (autoScrollRAF.current) {
      cancelAnimationFrame(autoScrollRAF.current);
      autoScrollRAF.current = null;
    }
    setDraggedTaskId(null);
    setDropTargetTaskId(null);
    setDropPosition(null);
    setGhostPosition(null); // v0.17.146: Clear ghost
    isDraggingRef.current = false;
    setIsDraggingState(false);
  };

  // v0.17.68: Set up global drag listeners
  useEffect(() => {
    if (draggedTaskId) {
      document.addEventListener('mousemove', handleDragMove);
      document.addEventListener('mouseup', handleDragEnd);
      document.body.style.cursor = 'grabbing';
      document.body.style.userSelect = 'none';

      return () => {
        document.removeEventListener('mousemove', handleDragMove);
        document.removeEventListener('mouseup', handleDragEnd);
        document.body.style.cursor = '';
        document.body.style.userSelect = '';
      };
    }
    return undefined;
  }, [draggedTaskId, dropTargetTaskId, dropPosition]);

  // Render cell content based on column type
  /*
   * Gantt v6 (Asakaa) · las celdas de la maqueta: nombre con guías de árbol, código WBS a la
   * derecha en mono, responsable en un avatar de 22 px, % en mono. Las fechas usan la celda de
   * siempre (con su selector), en formato corto.
   */
  /* Gantt ronda 2 (Yesid) · R5 · los antepasados de cada tarea, para el tooltip con su ruta («6.3 Tablero 3 › …») */
  const antepasadosDe = useMemo(() => {
    const m = new Map<string, Array<{ name: string; wbsCode?: string }>>();
    const recorrer = (ts: Task[], cadena: Array<{ name: string; wbsCode?: string }>) => {
      for (const t of ts) {
        m.set(t.id, cadena);
        if (t.subtasks?.length) recorrer(t.subtasks, [...cadena, { name: t.name, wbsCode: t.wbsCode }]);
      }
    };
    recorrer(tasks, []);
    return m;
  }, [tasks]);
  /* Ronda 3 (Yesid, 2-nov) · A1 · cuánto inicio comparte cada tarea con sus hermanas: sólo esas se cortan por el medio */
  const prefijoConHermanas = useMemo(() => {
    const m = new Map<string, number>();
    const recorrer = (ts: Task[]) => {
      const p = prefijosConHermanas(ts.map((t) => t.name));
      ts.forEach((t, i) => {
        m.set(t.id, p[i] ?? 0);
        if (t.subtasks?.length) recorrer(t.subtasks);
      });
    };
    recorrer(tasks);
    return m;
  }, [tasks]);
  /* R5 · la sangría por nivel, como mucho 12 px (con 5 niveles, 20 px se comían media columna) */
  const SANGRIA_V6 = 12;
  const celdaV6 = (column: GanttColumn, task: Task, level: number, isParentTask: boolean): React.ReactNode | undefined => {
    if (column.id === 'name') {
      const isEditing = editingTaskId === task.id;
      const isHovered = hoveredTaskId === task.id;
      return (
        <div data-celda-nombre-v6 className="flex items-center min-w-0 relative" style={{ gap: 6, alignSelf: 'stretch', width: '100%', paddingLeft: `${level * SANGRIA_V6}px` }}>
          {Array.from({ length: level }, (_, i) => (
            <span key={i} aria-hidden style={{ position: 'absolute', left: 8 + i * SANGRIA_V6, top: 0, bottom: 0, width: 1, background: 'var(--v6-separador, #CDD2D8)' }} />
          ))}
          {onTaskReparent && isHovered && !isEditing && (
            <div
              className="cursor-grab active:cursor-grabbing flex items-center"
              style={{ position: 'absolute', left: -10, top: 0, bottom: 0, width: 10, color: 'var(--v6-tenue, #5F6972)' }}
              onMouseDown={(e) => handleDragStart(task.id, e)}
              title={esGrid ? 'Arrastrar para mover la tarea' : 'Drag to move the task'}
            >
              <GripVertical style={{ width: 10, height: 14 }} />
            </div>
          )}
          {isParentTask ? (
            <button
              type="button"
              onClick={(e) => { e.stopPropagation(); onTaskToggle?.(task.id); }}
              aria-label={esGrid ? (task.isExpanded ? `Contraer ${task.name}` : `Desplegar ${task.name}`) : (task.isExpanded ? `Collapse ${task.name}` : `Expand ${task.name}`)}
              aria-expanded={!!task.isExpanded}
              style={{ flex: 'none', width: 18, height: 18, padding: 0, display: 'flex', alignItems: 'center', justifyContent: 'center', border: 0, borderRadius: 6, background: 'transparent', color: 'var(--v6-tenue, #5F6972)', cursor: 'pointer' }}
            >
              {task.isExpanded ? <ChevronDown style={{ width: 14, height: 14 }} strokeWidth={2} /> : <ChevronRight style={{ width: 14, height: 14 }} strokeWidth={2} />}
            </button>
          ) : (
            <span aria-hidden style={{ flex: 'none', width: 18 }} />
          )}
          {task.wbsCode && (
            <span style={{ flex: 'none', minWidth: 28, textAlign: 'right', fontFamily: "'JetBrains Mono', ui-monospace, monospace", fontVariantNumeric: 'tabular-nums', fontSize: 11, color: 'var(--v6-tenue, #5F6972)' }}>
              {task.wbsCode}
            </span>
          )}
          {isEditing ? (
            <input
              ref={editInputRef}
              placeholder={task.id === tareaPorNombrar ? (esGrid ? 'Nombre de la tarea' : 'Task name') : undefined}
              type="text"
              value={editingTaskName}
              onChange={(e) => setEditingTaskName(e.target.value)}
              onKeyDown={(e) => {
                e.stopPropagation();
                if (e.key === 'Escape') { handleRenameCancel(); return; }
                /* A12 · dentro de la celda, Enter guarda y crea la siguiente; Tab sangra y Mayús+Tab quita sangría. */
                /* sin nombre no se encadena otra: así no quedan filas «New Task» vacías */
                if (e.key === 'Enter') { const conNombre = !!editingTaskName.trim(); handleRenameSave(task.id); if (conNombre) onTaskCreate?.(task.id, 'below'); return; }
                if (e.key === 'Tab') {
                  e.preventDefault();
                  /* la recién insertada aún no está guardada: Tab le guarda el nombre a su nivel; la sangría, después (E5) */
                  if (handleRenameSave(task.id)) return;
                  if (e.shiftKey) onTaskOutdent?.([task.id]); else onTaskIndent?.([task.id]);
                }
              }}
              onBlur={() => handleRenameSave(task.id)}
              className="flex-1 min-w-0 px-2 py-1 rounded border outline-none"
              style={{ background: 'var(--v6-tarjeta, #fff)', borderColor: 'var(--v6-acento, #0FA392)', color: 'var(--v6-texto, #0E1114)', font: 'inherit', fontSize: 13 }}
              onClick={(e) => e.stopPropagation()}
            />
          ) : (
            (() => {
              /* Ronda 3 · A1 · el corte va al FINAL («…»); por el medio sólo con hermanas que empiezan igual: entonces el
                 comienzo se encoge con «…» (sin bajar de 12 caracteres) y la cola, lo que las distingue, se ve */
              const { comienzo, cola } = partirNombre(task.name, prefijoConHermanas.get(task.id) ?? 0);
              const antepasados = antepasadosDe.get(task.id) ?? [];
              return (
                <span
                  title={antepasados.length ? rutaDelNombre(antepasados, task.name) : task.name}
                  data-nombre-v6
                  style={{ marginLeft: 2, flex: '1 1 auto', minWidth: 0, display: 'flex', whiteSpace: 'nowrap', fontSize: 13, fontWeight: isParentTask || task.isMilestone ? 600 : 500, color: 'var(--v6-texto, #0E1114)' }}
                >
                  <span style={{ minWidth: cola && comienzo.length > MIN_COMIENZO ? `${MIN_COMIENZO}ch` : 0, overflow: 'hidden', textOverflow: 'ellipsis', flex: '0 1 auto' }}>{comienzo}</span>
                  {/* la cola nunca pasa del 60 % de la celda: el comienzo siempre se ve (Arcadio, P25038 30-oct) */}
                  {cola && <span style={{ flex: 'none', whiteSpace: 'pre', maxWidth: '60%', overflow: 'hidden', textOverflow: 'ellipsis' }}>{cola}</span>}
                </span>
              );
            })()
          )}
          {task.fijada && <Lock aria-label={esGrid ? 'Fechas fijadas' : 'Dates locked'} data-tarea-fijada style={{ flex: 'none', width: 11, height: 11, color: 'var(--v6-tenue, #5F6972)' }} />}
          <PuntoDeRiesgo riesgos={task.riesgos} es={esGrid} />
          {showCriticalPath && task.isCriticalPath && (
            <span aria-label={esGrid ? 'En la ruta crítica' : 'On the critical path'} style={{ flex: 'none', width: 6, height: 6, borderRadius: '50%', background: 'var(--v6-rojo-punto, #D13A40)' }} />
          )}
          {isHovered && !isEditing && (
            <div className="flex items-center" style={{ gap: 2, flex: 'none' }} onClick={(e) => e.stopPropagation()}>
              <button type="button" onClick={(e) => handleCreateSubtaskClick(task, e)} aria-label={esGrid ? 'Crear subtarea' : 'Create subtask'} title={esGrid ? 'Crear subtarea' : 'Create subtask'} style={{ width: 20, height: 20, padding: 0, display: 'flex', alignItems: 'center', justifyContent: 'center', border: 0, borderRadius: 6, background: 'transparent', color: 'var(--v6-tenue, #5F6972)', cursor: 'pointer' }}>
                <Plus style={{ width: 13, height: 13 }} />
              </button>
              <button type="button" onClick={(e) => { e.stopPropagation(); handleRenameStart(task); }} aria-label={esGrid ? 'Renombrar (F2)' : 'Rename (F2)'} title={esGrid ? 'Renombrar (F2)' : 'Rename (F2)'} style={{ width: 20, height: 20, padding: 0, display: 'flex', alignItems: 'center', justifyContent: 'center', border: 0, borderRadius: 6, background: 'transparent', color: 'var(--v6-tenue, #5F6972)', cursor: 'pointer' }}>
                <Edit3 style={{ width: 13, height: 13 }} />
              </button>
            </div>
          )}
        </div>
      );
    }
    if (column.id === 'assignees') {
      if (isParentTask) return <span aria-hidden />;
      const asignados: User[] = availableUsers.filter((user) =>
        task.assignees?.some((a) => ((a as any).id ? (a as any).id === user.id : (a.name === user.name || a.initials === user.initials))),
      );
      return (
        <div className="flex items-center justify-center w-full" onClick={(e) => e.stopPropagation()}>
          <UserAssignmentSelector
            variante="v6"
            es={esGrid}
            nombreDeLaTarea={task.name}
            assignedUsers={asignados}
            availableUsers={availableUsers}
            onChange={(users: User[]) => onTaskUpdate?.(task.id, { assignees: users.map((u) => ({ id: u.id, name: u.name, initials: u.initials, color: u.color })) })}
          />
        </div>
      );
    }
    if (columnasV6 && column.id === 'duration' && !isParentTask && task.startDate && task.endDate && !task.isMilestone && puedeEditarEnTabla(task)) {
      const cal = columnasV6.contexto.cal;
      const dias = habilesEntre(new Date(task.startDate), new Date(task.endDate), cal);
      return (
        <CeldaNumericaV6 valor={dias} sufijo="d" min={1} max={3650} etiqueta={`${esGrid ? 'Duración de' : 'Duration of'} ${task.name}`}
          alGuardar={(n) => onDuracionEnTabla?.(task, n)} />
      );
    }
    if (columnasV6 && column.id === 'predecessors' && !isParentTask && onTaskDependencies && puedeEditarEnTabla(task)) {
      const texto = textoDeColumna('predecessors', task, columnasV6.contexto);
      return (
        <button type="button" data-celda-v6="predecessors" className="truncate w-full" title={esGrid ? 'Editar predecesoras' : 'Edit predecessors'}
          onClick={(e) => { e.stopPropagation(); onTaskDependencies(task); }}
          style={{ textAlign: 'left', background: 'transparent', border: 0, padding: 0, cursor: 'pointer', fontFamily: "'JetBrains Mono', ui-monospace, monospace", fontSize: 12, color: texto === '—' ? 'var(--v6-tenue, #5F6972)' : 'var(--v6-texto-2, #4D5761)' }}>
          {texto}
        </button>
      );
    }
    if (columnasV6 && COLUMNAS_OPCIONALES.some((c) => c.id === column.id)) {
      const tono = tonoDeColumna(column.id, task, columnasV6.contexto.cal);
      const texto = textoDeColumna(column.id, task, columnasV6.contexto);
      return (
        <div className="truncate w-full" data-celda-v6={column.id} title={column.id === 'predecessors' && texto !== '—' ? texto : undefined}
          style={{ fontFamily: "'JetBrains Mono', ui-monospace, monospace", fontVariantNumeric: 'tabular-nums', fontSize: 12, fontWeight: isParentTask ? 500 : 400,
            color: tono === 'rojo' ? 'var(--v6-rojo, #B02A33)' : tono === 'verde' ? 'var(--v6-acento-texto, #066A5F)' : texto === '—' ? 'var(--v6-tenue, #5F6972)' : 'var(--v6-texto-2, #4D5761)' }}>
          {texto}
        </div>
      );
    }
    if (column.id === 'progress' && !isParentTask && onProgresoEnTabla && puedeEditarEnTabla(task)) {
      const p = Math.round(task.progress || 0);
      return (
        <CeldaNumericaV6 valor={p} sufijo="%" min={0} max={100} derecha etiqueta={`${esGrid ? 'Avance de' : 'Progress of'} ${task.name}`}
          alGuardar={(n) => onProgresoEnTabla(task, n)} />
      );
    }
    if (column.id === 'progress') {
      const p = Math.round(task.progress || 0);
      const enCurso = !isParentTask && p > 0 && p < 100;
      return (
        <div className="w-full" style={{ textAlign: 'right', fontFamily: "'JetBrains Mono', ui-monospace, monospace", fontVariantNumeric: 'tabular-nums', fontSize: 12,
          fontWeight: isParentTask || enCurso ? 500 : 400,
          color: enCurso ? 'var(--v6-acento-texto, #066A5F)' : p === 0 ? 'var(--v6-tenue, #5F6972)' : 'var(--v6-texto, #0E1114)' }}>
          {p}%
        </div>
      );
    }
    return undefined;
  };

  const renderCellContent = (column: GanttColumn, task: Task, level: number) => {
    // Leaf Node Rule: parent tasks with children are read-only containers
    const isParentTask = task.subtasks && task.subtasks.length > 0;
    if (v6) { const c = celdaV6(column, task, level, !!isParentTask); if (c !== undefined) return c; }

    switch (column.id) {
      case 'name':
        const isEditing = editingTaskId === task.id;
        const isHovered = hoveredTaskId === task.id;

        return (
          <div className="flex items-center gap-2 flex-1 min-w-0 relative" style={{ paddingLeft: `${level * 20}px` }}>
            {/* v0.17.68: Drag handle for reparenting - always visible, more prominent on hover */}
            {onTaskReparent && (
              <div
                className="cursor-grab active:cursor-grabbing p-0.5 rounded hover:bg-white/10 transition-all flex-shrink-0"
                style={{
                  color: theme.textTertiary,
                  opacity: isHovered ? 1 : 0.3,
                }}
                onMouseDown={(e) => handleDragStart(task.id, e)}
                title="Arrastrar para mover tarea"
              >
                <GripVertical className="w-4 h-4" />
              </div>
            )}

            {/* Expand/Collapse Button OR Color Indicator - same position for alignment */}
            {task.subtasks && task.subtasks.length > 0 ? (
              <button
                onClick={(e) => {
                  e.stopPropagation();
                  onTaskToggle?.(task.id);
                }}
                /* QA Asakaa 2.6.1 · un botón de solo icono necesita nombre para los lectores de pantalla. */
                aria-label={esGrid ? (task.isExpanded ? `Contraer ${task.name}` : `Desplegar ${task.name}`) : (task.isExpanded ? `Collapse ${task.name}` : `Expand ${task.name}`)}
                aria-expanded={!!task.isExpanded}
                className="p-0.5 hover:bg-opacity-10 rounded transition-colors flex-shrink-0"
                style={{ color: theme.textSecondary }}
              >
                {task.isExpanded ? (
                  <ChevronDown className="w-4 h-4" />
                ) : (
                  <ChevronRight className="w-4 h-4" />
                )}
              </button>
            ) : (
              /* v2.2.0: Removed color dot — spacer keeps alignment with chevron */
              <div className="w-5 h-5 flex-shrink-0" />
            )}

            {/* Task Name or Input */}
            {isEditing ? (
              <input
                ref={editInputRef}
                placeholder={task.id === tareaPorNombrar ? (esGrid ? 'Nombre de la tarea' : 'Task name') : undefined}
                type="text"
                value={editingTaskName}
                onChange={(e) => setEditingTaskName(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === 'Enter') {
                    handleRenameSave(task.id);
                  } else if (e.key === 'Escape') {
                    handleRenameCancel();
                  }
                }}
                onBlur={() => handleRenameSave(task.id)}
                className="flex-1 px-2 py-1 rounded border outline-none"
                style={{
                  backgroundColor: theme.bgPrimary,
                  borderColor: theme.accent,
                  color: theme.textPrimary,
                  fontFamily: 'Inter, sans-serif',
                  fontSize: '13px',
                  fontWeight: 500,
                }}
                onClick={(e) => e.stopPropagation()}
              />
            ) : (
              <>
                <span
                  className="flex-1 min-w-0"
                  style={{
                    // v0.17.72: Enhanced visual hierarchy - Root tasks (level 0) are always "phases"
                    display: 'flex',
                    alignItems: 'baseline',
                    gap: '6px',
                    color: !task.parentId
                      ? theme.textPrimary
                      : theme.textSecondary,
                    fontFamily: 'Inter, sans-serif',
                    fontSize: !task.parentId
                      ? '14px'
                      : '13px',
                    fontWeight: task.isMilestone
                      ? 600
                      : !task.parentId
                        ? 600
                        : 400,
                    letterSpacing: !task.parentId
                      ? '-0.01em'
                      : '0',
                  }}
                  title={task.name}
                >
                  {task.wbsCode && (
                    <span style={{
                      color: `var(--pj-texto-tenue, ${theme.textTertiary})`,
                      fontFamily: "'JetBrains Mono', monospace",
                      fontSize: '11px',
                      fontWeight: 500,
                      flexShrink: 0,
                    }}>
                      {task.wbsCode}
                    </span>
                  )}
                  {/* v5.2.0: Estrella de Reconocimiento */}
                  {(task as any).isHighlighted && task.status === 'completed' && (
                    <span
                      title="★"
                      style={{
                        color: '#F59E0B',
                        fontSize: '10px',
                        flexShrink: 0,
                        lineHeight: 1,
                      }}
                    >★</span>
                  )}
                  <span style={{
                    flex: 1,
                    minWidth: 0,
                    overflow: 'hidden',
                    textOverflow: 'ellipsis',
                    whiteSpace: 'nowrap',
                  }}>
                    {task.name}
                  </span>
                  {/* v5.0.0: Master/summary tasks show progress percentage */}
                  {task.subtasks && task.subtasks.length > 0 && (
                    <span style={{
                      color: '#6B7280',
                      fontFamily: "'JetBrains Mono', monospace",
                      fontSize: '12px',
                      fontWeight: 400,
                      flexShrink: 0,
                      whiteSpace: 'nowrap',
                    }}>
                      · {Math.round(task.progress || 0)}%
                    </span>
                  )}
                  {/* v5.1.0: CPM — critical dot + float indicator */}
                  {showCriticalPath && task.isCriticalPath && (
                    <span style={{
                      display: 'inline-block',
                      width: '6px',
                      height: '6px',
                      borderRadius: '50%',
                      backgroundColor: '#EF4444',
                      flexShrink: 0,
                      marginLeft: '2px',
                    }} />
                  )}
                  {showCriticalPath && task.cpmData && (
                    <span title={esGrid ? 'Días que la tarea puede retrasarse sin mover el fin del proyecto' : 'Total float: days the task can slip without moving the project end'} style={{
                      color: task.cpmData.totalFloat <= 0 ? '#EF4444'
                        : task.cpmData.totalFloat <= 5 ? '#F59E0B'
                        : '#6B7280',
                      fontFamily: "'JetBrains Mono', monospace",
                      fontSize: '10px',
                      fontWeight: 500,
                      flexShrink: 0,
                      whiteSpace: 'nowrap',
                      marginLeft: '4px',
                    }}>
                      {esGrid ? `Holgura: ${Math.round(task.cpmData.totalFloat)} d` : `TF: ${Math.round(task.cpmData.totalFloat)}d`}
                    </span>
                  )}
                </span>

                {/* Hover Action Buttons */}
                {isHovered && !isEditing && (
                  <div className="flex items-center gap-1 ml-2" onClick={(e) => e.stopPropagation()}>
                    {/* Create Subtask Button */}
                    <button
                      onClick={(e) => handleCreateSubtaskClick(task, e)}
                      className="p-1 rounded hover:bg-opacity-20 transition-colors"
                      style={{
                        color: theme.textTertiary,
                        backgroundColor: 'transparent'
                      }}
                      title="Create subtask"
                    >
                      <Plus className="w-3.5 h-3.5" />
                    </button>

                    {/* Rename Button */}
                    <button
                      onClick={(e) => {
                        e.stopPropagation();
                        handleRenameStart(task);
                      }}
                      className="p-1 rounded hover:bg-opacity-20 transition-colors"
                      style={{
                        color: theme.textTertiary,
                        backgroundColor: 'transparent'
                      }}
                      title="Rename (F2)"
                    >
                      <Edit3 className="w-3.5 h-3.5" />
                    </button>
                  </div>
                )}
              </>
            )}
          </div>
        );
      
      case 'startDate':
      case 'endDate':
        const isStartDate = column.id === 'startDate';
        const dateField = isStartDate ? 'startDate' : 'endDate';
        const dateValue = task[dateField];
        const isDatePickerOpen = datePickerState?.taskId === task.id && datePickerState?.field === dateField;

        const formatDisplayDate = (date: Date | string | undefined) => {
          if (!date) return v6 ? '—' : '-';
          const d = typeof date === 'string' ? new Date(date) : date;
          if (v6) return fechaCorta(d, esGrid ? 'es' : 'en'); /* R6: con su año si no es el actual */
          return d.toLocaleDateString(esGrid ? 'es-ES' : 'en-US', { day: '2-digit', month: '2-digit', year: 'numeric' });
        };

        return (
          <div
            className={`flex items-center w-full relative ${v6 ? 'justify-start' : 'justify-center'}`}
            onClick={(e) => e.stopPropagation()}
          >
            <button
              type="button"
              className={v6 ? 'flex items-center rounded' : 'flex items-center gap-1.5 px-2 py-1 rounded text-xs transition-colors hover:bg-white/5'}
              style={v6 ? {
                whiteSpace: 'nowrap', padding: 0, border: 0, background: 'transparent',
                fontFamily: "'JetBrains Mono', ui-monospace, monospace", fontVariantNumeric: 'tabular-nums', fontSize: 11,
                /* G2 · la fecha Fin de una vencida va en rojo */
                color: !isStartDate && pasaDeSuLimite(task) ? 'var(--v6-rojo, #B02A33)' : !isStartDate && !isParentTask && task.status !== 'completed' && (task.progress ?? 0) < 100 && dateValue && new Date(dateValue).getTime() < new Date(new Date().toDateString()).getTime()
                  ? 'var(--v6-rojo, #B02A33)' : 'var(--v6-texto-2, #4D5761)',
                cursor: isParentTask ? 'default' : 'pointer',
              } : {
                color: theme.textSecondary,
                opacity: isParentTask ? 0.5 : 1,
                cursor: isParentTask ? 'default' : 'pointer',
              }}
              title={isParentTask ? (esGrid ? 'Se calcula con sus subtareas' : 'Auto-calculated from subtasks') : undefined}
              onClick={(e) => {
                if (isParentTask) return; // Parent dates are read-only (roll-up)
                if (isDatePickerOpen) {
                  setDatePickerState(null);
                } else {
                  const rect = e.currentTarget.getBoundingClientRect();
                  setDatePickerState({
                    taskId: task.id,
                    field: dateField,
                    month: (dateValue ? (typeof dateValue === 'string' ? new Date(dateValue) : dateValue) : new Date()),
                    position: { top: rect.bottom + 4, left: rect.left }
                  });
                }
              }}
            >
              {!v6 && <Calendar className="w-3 h-3" style={{ color: theme.textTertiary }} />}
              <span>{formatDisplayDate(dateValue)}</span>
              {isParentTask && !v6 && <span style={{ fontSize: '9px', color: theme.textTertiary, marginLeft: '2px' }}>▼</span>}
            </button>

            {/* Yesid (19-nov), «la v4 pide uno solo»: el calendario de la v4 (CalendarioDeFechaV4, mismas clases que el de la app).
                En un portal: fuera de los contenedores con overflow:hidden. */}
            {isDatePickerOpen && typeof document !== 'undefined' && createPortal(
              <>
                <div className="fixed inset-0 z-[9998]" onClick={() => setDatePickerState(null)} />
                <div
                  className="v4-pop v4-scope"
                  role="dialog"
                  aria-label={`${isStartDate ? (esGrid ? 'Inicio' : 'Start') : (esGrid ? 'Fin' : 'End')} · ${task.name}`}
                  data-calendario-del-gantt={dateField}
                  style={{
                    position: 'fixed',
                    zIndex: 9999,
                    padding: 0,
                    top: Math.min(datePickerState?.position.top ?? 0, window.innerHeight - 320),
                    left: Math.max(8, Math.min(datePickerState?.position.left ?? 0, window.innerWidth - 268)),
                  }}
                  onClick={(e) => e.stopPropagation()}
                >
                  <CalendarioDeFechaV4
                    valor={dateValue ? (typeof dateValue === 'string' ? new Date(dateValue) : dateValue) : null}
                    es={esGrid}
                    festivos={festivos}
                    alElegir={(d) => {
                      onTaskUpdate?.(task.id, { [dateField]: d });
                      setDatePickerState(null);
                    }}
                    alBorrar={dateValue ? () => {
                      onTaskUpdate?.(task.id, { [dateField]: undefined });
                      setDatePickerState(null);
                    } : undefined}
                    alCerrar={() => setDatePickerState(null)}
                  />
                </div>
              </>,
              document.body
            )}
          </div>
        );

      case 'duration':
        return (
          <div className="flex items-center justify-center w-full">
            <span
              className="text-xs tabular-nums"
              style={{
                color: theme.textSecondary,
                fontFamily: 'Inter, sans-serif',
                fontWeight: 600,
              }}
            >
              {getDuration(task)}
            </span>
          </div>
        );
      
      case 'assignees':
        // Parent tasks: no assignees (read-only container)
        if (isParentTask) {
          return (
            <div className="flex items-center justify-center w-full" style={{ opacity: 0.4 }}>
              <span className="text-xs" style={{ color: theme.textTertiary }}>—</span>
            </div>
          );
        }
        // Match by id first (robust when two people share a name / initials,
        // e.g. a real user + a virtual profile). Fall back to name/initials only
        // for legacy assignees that were stored without an id.
        const taskAssignedUsers: User[] = availableUsers.filter(user =>
          task.assignees?.some(a =>
            (a as any).id
              ? (a as any).id === user.id
              : (a.name === user.name || a.initials === user.initials)
          )
        );

        return (
          <div
            className="flex items-center justify-center w-full"
            onClick={(e) => e.stopPropagation()}
          >
            <UserAssignmentSelector
              assignedUsers={taskAssignedUsers}
              availableUsers={availableUsers}
              onChange={(users: User[]) => {
                const newAssignees = users.map(u => ({
                  id: u.id,
                  name: u.name,
                  initials: u.initials,
                  color: u.color
                }));
                // Pass an empty array (not undefined) when cleared, so consumers
                // that only sync assignees "when defined" still process the
                // removal and delete the rows. undefined = "untouched", [] = "none".
                onTaskUpdate?.(task.id, {
                  assignees: newAssignees,
                });
              }}
            />
          </div>
        );

      case 'status':
        // Parent tasks: show rolled-up status (read-only)
        if (isParentTask) {
          const statusLabel = task.progress === 100 ? '✓' : task.progress > 0 ? '◐' : '○';
          return (
            <div className="flex items-center justify-center w-full" style={{ opacity: 0.5 }}>
              <span className="text-xs" style={{ color: theme.textTertiary }}>{statusLabel}</span>
            </div>
          );
        }
        return (
          <div
            className="flex items-center justify-center w-full"
            onClick={(e) => e.stopPropagation()}
          >
            <StatusSelector
              status={task.status || 'todo'}
              onChange={(status) => {
                onTaskUpdate?.(task.id, {
                  status,
                  progress: status === 'completed' ? 100 : task.progress
                });
              }}
            />
          </div>
        );

      case 'progress':
        return (
          <div className="flex items-center justify-center gap-2 w-full" style={{ opacity: isParentTask ? 0.6 : 1 }}>
            <div className="flex-1 h-1.5 rounded-full overflow-hidden max-w-[60px]" style={{ backgroundColor: theme.bgSecondary }}>
              <div
                className="h-full rounded-full transition-all"
                style={{
                  width: `${task.progress}%`,
                  backgroundColor: task.progress === 100 ? theme.statusCompleted : theme.accent,
                }}
              />
            </div>
            <span
              className="text-xs tabular-nums min-w-[35px] text-right"
              style={{
                color: theme.textTertiary,
                fontFamily: 'Inter, sans-serif',
                fontWeight: 600,
              }}
            >
              {task.progress}%
            </span>
          </div>
        );

      // v0.17.29: Priority column
      case 'priority':
        // Map task priority to PrioritySelector format
        const priorityMapForSelector: Record<string, 'LOW' | 'MEDIUM' | 'HIGH' | 'URGENT'> = {
          low: 'LOW',
          medium: 'MEDIUM',
          high: 'HIGH',
          urgent: 'URGENT',
        };
        const reversePriorityMapForTask: Record<string, 'low' | 'medium' | 'high' | 'urgent'> = {
          LOW: 'low',
          MEDIUM: 'medium',
          HIGH: 'high',
          URGENT: 'urgent',
        };
        const currentPriorityValue = priorityMapForSelector[task.priority || 'medium'] || 'MEDIUM';

        return (
          <div
            className="flex items-center justify-center w-full"
            onClick={(e) => e.stopPropagation()}
          >
            <PrioritySelector
              priority={currentPriorityValue}
              onChange={(newPriority) => {
                if (newPriority) {
                  onTaskUpdate?.(task.id, {
                    priority: reversePriorityMapForTask[newPriority] || 'medium',
                  });
                }
              }}
            />
          </div>
        );

      default:
        return null;
    }
  };

  // Context menu items for header
  const getHeaderContextMenuItems = (columnId: ColumnType): ContextMenuItem[] => {
    return [
      {
        id: 'hide',
        label: 'Hide Column',
        icon: MenuIcons.Hide,
        onClick: () => onToggleColumn(columnId),
        disabled: columnId === 'name',
      },
      { id: 'sep1', label: '', onClick: () => {}, separator: true },
      {
        id: 'sortAsc',
        label: 'Sort Ascending',
        icon: MenuIcons.SortAsc,
        onClick: () => {
          // Implement sorting in parent component if needed
        },
      },
      {
        id: 'sortDesc',
        label: 'Sort Descending',
        icon: MenuIcons.SortDesc,
        onClick: () => {
          // Implement sorting in parent component if needed
        },
      },
    ];
  };

  // v0.16.2: Context menu items for task row - unified with GanttBoard context menu
  // v0.17.46: Parent tasks (with subtasks) have limited menu - no edit, no status changes
  const getTaskContextMenuItems = (task: Task): ContextMenuItem[] => {
    const isParentTask = task.subtasks && task.subtasks.length > 0;

    // v1.9.6: Acciones masivas — si la tarea bajo el cursor es parte de una
    // multi-selección (Ctrl/Shift+click), las acciones de estado, duplicar y
    // eliminar aplican a TODAS las tareas seleccionadas. Editar / Agregar
    // subtarea / Dividir siguen siendo de una sola tarea.
    const flatAll = flattenTasksUtil(tasks);
    const isBulk = selectedTaskIds.size > 1 && selectedTaskIds.has(task.id);
    const selectedTasks = isBulk
      ? flatAll.filter((t) => selectedTaskIds.has(t.id))
      : [task];
    const bulkIds = selectedTasks.map((t) => t.id);
    // Cambios de estado solo a tareas hoja: el estado/progreso de los padres
    // se auto-calcula desde sus subtareas.
    const statusTargets = selectedTasks.filter(
      (t) => !(t.subtasks && t.subtasks.length > 0)
    );
    const sfx = isBulk ? ` (${bulkIds.length})` : '';
    const requestDelete = () => {
      if (onDeleteRequest) {
        // En bulk el modal muestra solo el conteo; el nombre aplica al caso single.
        onDeleteRequest(bulkIds, task.name);
      } else {
        onMultiTaskDelete?.(bulkIds);
      }
    };

    // QA Asakaa E14: el mismo menú, en el mismo orden, en todas las filas; lo que no aplica a una fase sale apagado.
    // (Antes una fase tenía 3 opciones y «Duplicar» caía donde las demás filas tienen «Agregar subtarea».)
    const cm = translations?.contextMenu;
    return armarMenuDeLaTarea({
      edit: {
        label: cm?.editTask || 'Edit Task', icon: MenuIcons.Pencil, onClick: () => onTaskDblClick?.(task), disabled: !!isParentTask,
        /* QA Latty R3 · BUG-41 · el mismo motivo que el menú de la barra */
        motivo: isParentTask ? (esGrid ? 'Una fase se calcula con sus tareas: abre su panel para el nombre' : 'A phase comes from its tasks: open its panel to rename it') : undefined,
      },
      addSubtask: { label: cm?.addSubtask || 'Add Subtask', icon: MenuIcons.Add, onClick: () => onCreateSubtask?.(task.id) },
      ...(onTaskIndent ? {
        indent: { label: cm?.indent || 'Indent', icon: MenuIcons.Indent, onClick: () => onTaskIndent([task.id]), disabled: isBulk || !hermanaDeArriba(tasks, task.id) },
      } : {}),
      ...(onTaskOutdent ? {
        outdent: { label: cm?.outdent || 'Outdent', icon: MenuIcons.Outdent, onClick: () => onTaskOutdent([task.id]), disabled: isBulk || !tienePadre(tasks, task.id) },
      } : {}),
      // QA Asakaa E14: las dependencias también se editan después de crear la tarea.
      ...(onTaskDependencies ? {
        dependencies: { label: cm?.dependencies || 'Dependencies…', icon: MenuIcons.Link, onClick: () => onTaskDependencies(task), disabled: !!isParentTask },
      } : {}),
      // QA Asakaa 2.3.5: «añadir "Convertir en hito" al menú contextual». Solo en tareas sin hijas.
      ...(onTaskUpdate ? {
        milestone: {
          label: task.isMilestone ? (esGrid ? 'Quitar hito' : 'Remove milestone') : (esGrid ? 'Convertir en hito' : 'Convert to milestone'),
          icon: MenuIcons.Milestone, onClick: () => onTaskUpdate(task.id, { isMilestone: !task.isMilestone }), disabled: !!isParentTask,
        },
      } : {}),
      // Cambios de estado — bulk-aware; los padres los calculan de sus hijas
      markIncomplete: {
        label: (cm?.markIncomplete || 'Mark Incomplete') + sfx, icon: MenuIcons.MarkIncomplete,
        onClick: () => statusTargets.forEach((t) => onTaskUpdate?.(t.id, { status: 'todo', progress: 0 })),
        disabled: statusTargets.length === 0 || statusTargets.every((t) => t.status === 'todo'),
      },
      setInProgress: {
        label: (cm?.setInProgress || 'Set In Progress') + sfx, icon: MenuIcons.SetInProgress,
        onClick: () => statusTargets.forEach((t) => onTaskUpdate?.(t.id, { status: 'in-progress' })),
        disabled: statusTargets.length === 0 || statusTargets.every((t) => t.status === 'in-progress'),
      },
      markComplete: {
        label: (cm?.markComplete || 'Mark Complete') + sfx, icon: MenuIcons.MarkComplete,
        onClick: () => statusTargets.forEach((t) => onTaskUpdate?.(t.id, { status: 'completed', progress: 100 })),
        disabled: statusTargets.length === 0 || statusTargets.every((t) => t.status === 'completed'),
      },
      // v1.4.3: Duplicate Task — bulk-aware
      duplicate: { label: (cm?.duplicateTask || 'Duplicate Task') + sfx, icon: MenuIcons.Duplicate, onClick: () => onTaskDuplicate?.(bulkIds) },
      // Split Task: solo desde el menú de la barra (clic derecho en el diagrama)
      /* QA Latty R3 · BUG-41 · «Dividir tarea» salía apagada sin decir por qué: aquí se dice dónde se hace */
      split: {
        label: cm?.splitTask || 'Split Task', icon: MenuIcons.Split, onClick: () => {}, disabled: true,
        motivo: isParentTask ? (esGrid ? 'Una fase no se divide: divide sus tareas' : 'A phase cannot be split: split its tasks')
          : (esGrid ? 'Se divide desde su barra: clic derecho sobre la barra en el diagrama' : 'Split it from its bar: right-click the bar in the chart'),
      },
      // Delete Task - v0.17.34: Use confirmation modal if available — bulk-aware
      delete: { label: (cm?.deleteTask || 'Delete Task') + sfx, icon: MenuIcons.Delete, onClick: requestDelete },
    });
  };

  const visibleColumns = columns.filter(col => col.visible);

  // v0.17.213: Buttons now in flex flow, no extra width needed
  const totalColumnsWidth = visibleColumns.reduce((sum, col) => sum + col.width, 0);

  // v0.13.10: TaskGrid no longer has its own scroll - it syncs with Timeline scroll
  // v0.17.372: Removed h-full to allow sticky header to work correctly during scroll
  return (
    <div
      className="gantt-taskgrid-content"
      style={{
        backgroundColor: v6 ? 'var(--v6-tarjeta, #FFFFFF)' : theme.bgPrimary,
        minWidth: totalColumnsWidth, // v0.17.194: Enable horizontal scroll when needed
      }}
    >
      {/* Gantt v6 · cabecera de dos pisos: el resumen y «contraer todo» (24) y los títulos (36). */}
      {v6 ? (
        <div
          data-cabecera-tabla-v6
          className="sticky top-0 z-10 flex flex-col"
          style={{ height: `${HEADER_HEIGHT}px`, boxSizing: 'border-box', background: 'var(--v6-tarjeta, #FFFFFF)', borderBottom: '1px solid var(--v6-borde, #E2E5E9)' }}
        >
          <div style={{ height: 24, boxSizing: 'border-box', display: 'flex', alignItems: 'center', justifyContent: 'space-between', padding: '0 10px 0 14px', borderBottom: '1px solid var(--v6-linea, #EEF0F2)', fontSize: 11, color: 'var(--v6-tenue, #5F6972)' }}>
            <span className="truncate" data-resumen-v6>
              {resumenV6}
              {onMostrarOcultas && (
                <>
                  {' · '}
                  <button type="button" onClick={onMostrarOcultas} data-mostrar-ocultas
                    style={{ border: 0, padding: 0, background: 'transparent', font: 'inherit', color: 'var(--v6-acento-texto, #087F72)', fontWeight: 500, cursor: 'pointer', textDecoration: 'underline', textUnderlineOffset: 2 }}>
                    {esGrid ? 'Mostrar' : 'Show'}
                  </button>
                </>
              )}
              {onOcultarCompletadas && (
                <>
                  {' · '}
                  <button type="button" onClick={onOcultarCompletadas} data-ocultar-completadas
                    style={{ border: 0, padding: 0, background: 'transparent', font: 'inherit', color: 'var(--v6-acento-texto, #087F72)', cursor: 'pointer' }}>
                    {/* N14: «… completadas a la vista · Ocultar», como la Lista */ esGrid ? 'Ocultar' : 'Hide'}
                  </button>
                </>
              )}
              {avisoVencidas && onVerVencidas && (
                <>
                  {' · '}
                  <span data-aviso-vencidas style={{ color: 'var(--v6-rojo, #B02A33)', fontWeight: 500 }}>{avisoVencidas}</span>
                  {' · '}
                  <button type="button" onClick={onVerVencidas} data-ver-vencidas
                    style={{ border: 0, padding: 0, background: 'transparent', font: 'inherit', color: 'var(--v6-acento-texto, #087F72)', fontWeight: 500, cursor: 'pointer', textDecoration: 'underline', textUnderlineOffset: 2 }}>
                    {esGrid ? 'Ver' : 'View'}
                  </button>
                </>
              )}
            </span>
            {onContraerTodo && (
              <button
                type="button"
                onClick={onContraerTodo}
                aria-label={esGrid ? 'Contraer todos los grupos' : 'Collapse all groups'}
                title={esGrid ? 'Contraer todos los grupos' : 'Collapse all groups'}
                style={{ width: 20, height: 20, padding: 0, display: 'flex', alignItems: 'center', justifyContent: 'center', border: 0, borderRadius: 6, background: 'transparent', color: 'var(--v6-tenue, #5F6972)', cursor: 'pointer' }}
              >
                <ChevronsDownUp style={{ width: 13, height: 13 }} strokeWidth={2} />
              </button>
            )}
          </div>
          <div style={{ flex: 1, display: 'flex', alignItems: 'center', gap: 10, padding: '0 14px 0 10px', fontSize: 11, fontWeight: 500, color: 'var(--v6-tenue, #5F6972)' }}>
            {visibleColumns.map((c) => (
              <div
                key={c.id}
                style={{ width: c.id === 'name' ? undefined : c.width, flex: c.id === 'name' ? '1 1 0' : '0 0 auto', minWidth: 0, whiteSpace: 'nowrap', overflow: 'hidden',
                  textAlign: c.id === 'assignees' ? 'center' : c.id === 'progress' ? 'right' : 'left', paddingLeft: c.id === 'name' ? 60 : 0 }}
                title={c.id === 'assignees' ? c.label : undefined}
              >
                {/* Gantt ronda 2 (Yesid) · P1-5 · en 28 px «Owner» se cortaba («Owne»): un icono de persona con su nombre en
                    el tooltip y para el lector de pantalla, sin tocar el ancho de la v6. */}
                {c.id === 'assignees' && (c.width ?? 0) <= 40
                  ? <span role="img" aria-label={c.label} data-encabezado-responsable style={{ display: 'inline-flex', justifyContent: 'center', width: '100%' }}>
                      <IconoPersona aria-hidden style={{ width: 13, height: 13 }} strokeWidth={2} />
                    </span>
                  : c.label}
              </div>
            ))}
            {columnasV6 && (
              <MenuDeColumnasV6 es={esGrid} elegidas={columnasV6.elegidas} alternar={columnasV6.alternar}
                opciones={COLUMNAS_OPCIONALES.filter((c) => c.id !== 'cost' || columnasV6.verCostos)} />
            )}
          </div>
        </div>
      ) : (
      <div
        className="sticky top-0 z-10 flex items-center"
        style={{
          backgroundColor: theme.glassHeader || theme.bgSecondary,
          height: `${HEADER_HEIGHT}px`,
          paddingLeft: '3px',
          borderBottom: `1px solid ${theme.border}`,
          boxSizing: 'border-box',
        }}
      >
        {/* Columns container - takes remaining space */}
        <div className="flex items-center flex-1 min-w-0">
        {visibleColumns.map((column, colIndex) => {
          const isLastColumn = colIndex === visibleColumns.length - 1;
          const isNameColumn = column.id === 'name';

          return (
          <div
            key={column.id}
            className={`flex items-center px-4 cursor-pointer hover:bg-opacity-50 transition-colors relative ${
              isNameColumn ? '' : 'justify-center'
            }`}
            style={{
              // v0.17.129: All columns use fixed width for consistent resize behavior
              width: `${column.width}px`,
              minWidth: `${column.minWidth ?? (isNameColumn ? 200 : 60)}px`,
              maxWidth: `${column.maxWidth ?? 2000}px`,
              flexShrink: isNameColumn && visibleColumns.length === 1 ? 1 : 0,
              flexGrow: isNameColumn && visibleColumns.length === 1 ? 1 : 0,
              // v0.17.129: Border between columns, none on last (GanttBoard has the main divider)
              borderRight: !isLastColumn ? `1px solid ${theme.borderLight}` : 'none',
              height: '100%',
              boxSizing: 'border-box',
              overflow: 'hidden',
            }}
            onContextMenu={(e) => {
              e.preventDefault();
              setContextMenu({
                isOpen: true,
                x: e.clientX,
                y: e.clientY,
                type: 'header',
                columnId: column.id,
              });
            }}
            onMouseEnter={(e) => {
              e.currentTarget.style.backgroundColor = theme.hoverBg;
            }}
            onMouseLeave={(e) => {
              e.currentTarget.style.backgroundColor = 'transparent';
            }}
          >
            <span
              className="text-xs uppercase tracking-wider"
              style={{
                color: theme.textTertiary,
                fontFamily: 'Inter, sans-serif',
                fontWeight: 600,
                // v0.17.129: Truncate long labels elegantly
                overflow: 'hidden',
                textOverflow: 'ellipsis',
                whiteSpace: 'nowrap',
                minWidth: 0,
                // v0.17.191: No extra padding needed - buttons are now at header level
                paddingRight: '0',
              }}
              title={column.label}
            >
              {column.label}
            </span>

            {/* v0.17.191: Action buttons moved outside column flow - see header level */}

            {/* v0.13.8: Resize handle for resizable columns */}
            {/* v0.17.56: Improved resize handle - wider for easier grabbing */}
            {column.resizable && (
              <div
                className="absolute right-0 top-0 bottom-0 cursor-col-resize transition-colors group"
                style={{
                  width: '12px',
                  marginRight: '-6px',
                  backgroundColor: resizingColumn === column.id ? `${theme.accent}30` : 'transparent',
                  zIndex: 5,
                }}
                onMouseDown={(e) => {
                  e.preventDefault();
                  e.stopPropagation();
                  setResizingColumn(column.id);
                  setResizeStartX(e.clientX);
                  setResizeStartWidth(column.width);
                }}
                title={esGrid ? 'Arrastra para cambiar el ancho' : 'Drag to resize column'}
              >
                {/* Visual indicator line — always slightly visible, brighter on hover */}
                <div
                  className="absolute top-0 bottom-0 transition-opacity"
                  style={{
                    left: '5px',
                    width: '2px',
                    backgroundColor: theme.accent,
                    borderRadius: '1px',
                    opacity: resizingColumn === column.id ? 0.8 : undefined,
                  }}
                >
                  <div className="absolute inset-0 opacity-20 group-hover:opacity-80 transition-opacity" style={{ backgroundColor: theme.accent }} />
                </div>
              </div>
            )}
          </div>
        );
        })}
        </div>

        {/* v0.17.215: Action buttons with sticky positioning - always visible at right edge */}
        <div
          className="flex items-center gap-1 px-2"
          style={{
            position: 'sticky',
            right: 0,
            height: '100%',
            backgroundColor: theme.glassHeader || theme.bgSecondary,
            zIndex: 5,
          }}
        >
          <ColumnManager
            columns={columns}
            onToggleColumn={onToggleColumn}
            theme={theme}
          />
          <button
            onClick={() => setShowKeyboardHelp(!showKeyboardHelp)}
            className="p-1.5 rounded hover:bg-opacity-10 transition-colors"
            style={{ color: theme.textTertiary }}
            title="Keyboard shortcuts"
          >
            <Keyboard className="w-4 h-4" />
          </button>

          {/* Keyboard help tooltip */}
          {showKeyboardHelp && (
            <div
              ref={keyboardHelpRef}
              className="absolute top-full right-0 mt-2 p-4 rounded-lg shadow-2xl z-50 min-w-[400px]"
              style={{
                backgroundColor: theme.bgPrimary,
                border: `1px solid ${theme.border}`,
                color: theme.textPrimary,
              }}
              onClick={(e) => e.stopPropagation()}
            >
              <div className="flex items-center justify-between mb-3 pb-2 border-b" style={{ borderColor: theme.border }}>
                <h3 className="font-semibold text-sm" style={{ color: theme.textPrimary }}>Keyboard Shortcuts</h3>
                <button onClick={() => setShowKeyboardHelp(false)} className="text-xs px-2 py-1 rounded hover:bg-opacity-10" style={{ color: theme.textTertiary }}>Close</button>
              </div>
              <div className="space-y-3 text-xs">
                <div>
                  <div className="font-semibold mb-1.5" style={{ color: theme.textSecondary }}>Navigation</div>
                  <div className="space-y-1">
                    <div className="flex justify-between"><span style={{ color: theme.textTertiary }}>Move focus up/down</span><kbd className="px-2 py-0.5 rounded font-mono text-xs" style={{ backgroundColor: theme.bgGrid, color: theme.textPrimary }}>↑ / ↓</kbd></div>
                    <div className="flex justify-between"><span style={{ color: theme.textTertiary }}>Select range</span><kbd className="px-2 py-0.5 rounded font-mono text-xs" style={{ backgroundColor: theme.bgGrid, color: theme.textPrimary }}>Shift + ↑ / ↓</kbd></div>
                    <div className="flex justify-between"><span style={{ color: theme.textTertiary }}>Toggle selection</span><kbd className="px-2 py-0.5 rounded font-mono text-xs" style={{ backgroundColor: theme.bgGrid, color: theme.textPrimary }}>Cmd/Ctrl + Click</kbd></div>
                  </div>
                </div>
                <div>
                  <div className="font-semibold mb-1.5" style={{ color: theme.textSecondary }}>Hierarchy</div>
                  <div className="space-y-1">
                    <div className="flex justify-between"><span style={{ color: theme.textTertiary }}>Indent task</span><kbd className="px-2 py-0.5 rounded font-mono text-xs" style={{ backgroundColor: theme.bgGrid, color: theme.textPrimary }}>Tab</kbd></div>
                    <div className="flex justify-between"><span style={{ color: theme.textTertiary }}>Outdent task</span><kbd className="px-2 py-0.5 rounded font-mono text-xs" style={{ backgroundColor: theme.bgGrid, color: theme.textPrimary }}>Shift + Tab</kbd></div>
                    <div className="flex justify-between"><span style={{ color: theme.textTertiary }}>Expand/Collapse</span><kbd className="px-2 py-0.5 rounded font-mono text-xs" style={{ backgroundColor: theme.bgGrid, color: theme.textPrimary }}>→ / ←</kbd></div>
                  </div>
                </div>
                <div>
                  <div className="font-semibold mb-1.5" style={{ color: theme.textSecondary }}>Editing</div>
                  <div className="space-y-1">
                    <div className="flex justify-between"><span style={{ color: theme.textTertiary }}>Create task below</span><kbd className="px-2 py-0.5 rounded font-mono text-xs" style={{ backgroundColor: theme.bgGrid, color: theme.textPrimary }}>Enter</kbd></div>
                    <div className="flex justify-between"><span style={{ color: theme.textTertiary }}>Create task above</span><kbd className="px-2 py-0.5 rounded font-mono text-xs" style={{ backgroundColor: theme.bgGrid, color: theme.textPrimary }}>Shift + Enter</kbd></div>
                    <div className="flex justify-between"><span style={{ color: theme.textTertiary }}>Open task modal</span><kbd className="px-2 py-0.5 rounded font-mono text-xs" style={{ backgroundColor: theme.bgGrid, color: theme.textPrimary }}>Cmd/Ctrl + Enter</kbd></div>
                    <div className="flex justify-between"><span style={{ color: theme.textTertiary }}>Rename task</span><kbd className="px-2 py-0.5 rounded font-mono text-xs" style={{ backgroundColor: theme.bgGrid, color: theme.textPrimary }}>F2</kbd></div>
                  </div>
                </div>
                <div>
                  <div className="font-semibold mb-1.5" style={{ color: theme.textSecondary }}>Actions</div>
                  <div className="space-y-1">
                    <div className="flex justify-between"><span style={{ color: theme.textTertiary }}>Move task up/down</span><kbd className="px-2 py-0.5 rounded font-mono text-xs" style={{ backgroundColor: theme.bgGrid, color: theme.textPrimary }}>Alt + ↑ / ↓</kbd></div>
                    <div className="flex justify-between"><span style={{ color: theme.textTertiary }}>Delete task</span><kbd className="px-2 py-0.5 rounded font-mono text-xs" style={{ backgroundColor: theme.bgGrid, color: theme.textPrimary }}>Delete</kbd></div>
                    <div className="flex justify-between"><span style={{ color: theme.textTertiary }}>Duplicate task</span><kbd className="px-2 py-0.5 rounded font-mono text-xs" style={{ backgroundColor: theme.bgGrid, color: theme.textPrimary }}>Cmd/Ctrl + D</kbd></div>
                  </div>
                </div>
              </div>
            </div>
          )}
        </div>
      </div>
      )}

      {/* Task Rows Container - v0.17.222: Now uses real scroll instead of CSS transform */}
      {/* minHeight ensures scroll area matches Timeline for proper sync */}
      <div className="gantt-taskgrid-content" data-grid-body style={{ minHeight: contentHeight }}
        role="treegrid" aria-label={esGrid ? 'Tareas del Gantt' : 'Gantt tasks'} aria-rowcount={flatTasks.length}>
      {/* Gantt ronda 2 (Yesid) · R1 · VIRTUALIZAR: solo las filas de la franja visible (y un margen); arriba y abajo, su alto. */}
      {filasVisibles && filasVisibles.desde > 0 && <div aria-hidden data-relleno-arriba style={{ height: filasVisibles.desde * ROW_HEIGHT }} />}
      {flatTasks.map(({ task, level }, index) => {
        if (filasVisibles && (index < filasVisibles.desde || index > filasVisibles.hasta)) return null;
        const isSelected = isTaskSelected(task.id);
        const inFillRange = isInFillRange(index);

        // v0.17.146: Calculate drop indicator styles - ClickUp style with prominent line
        const isDropTarget = dropTargetTaskId === task.id;
        const showDropAbove = isDropTarget && dropPosition === 'above';
        const showDropBelow = isDropTarget && dropPosition === 'below';
        const showDropChild = isDropTarget && dropPosition === 'child';
        const dropStyles: React.CSSProperties = {};
        if (showDropChild) {
          dropStyles.backgroundColor = `${theme.accent}15`;
          dropStyles.boxShadow = `inset 0 0 0 2px ${theme.accent}`;
        }

        return (
          <motion.div
            key={task.id}
            data-task-row={task.id}
            role="row"
            aria-rowindex={index + 1}
            aria-level={level + 1}
            aria-expanded={task.subtasks?.length ? !!task.isExpanded : undefined}
            aria-selected={isSelected}
            tabIndex={v6 ? (task.id === filaConTab ? 0 : -1) : undefined}
            className={`flex items-center cursor-pointer group ${draggedTaskId === task.id ? 'opacity-50' : ''}`}
            style={{
              position: 'relative', // v0.17.146: For drop indicator positioning
              height: `${ROW_HEIGHT}px`,
              ...(v6 ? {
                boxSizing: 'border-box' as const,
                padding: '0 14px 0 10px',
                gap: 10,
                borderBottom: '1px solid var(--v6-linea, #EEF0F2)',
                boxShadow: isSelected ? 'inset 2px 0 0 var(--v6-acento, #0FA392)' : undefined,
                backgroundColor: isSelected ? 'var(--v6-fila-seleccionada, rgba(15,163,146,0.08))' : showDropChild ? `${theme.accent}15` : 'transparent',
              } : {
              borderLeft: isSelected ? `3px solid ${theme.accent}` : `3px solid transparent`,
              backgroundColor: isSelected
                ? theme.accentLight
                : showDropChild
                  ? `${theme.accent}15`
                  : (index % 2 === 0 ? theme.bgPrimary : theme.bgGrid),
              }),
              // v5.1.0: CPM opacity — non-critical tasks fade
              opacity: showCriticalPath ? (task.isCriticalPath ? 1.0 : 0.4) : undefined,
              transition: 'opacity 300ms ease',
              ...dropStyles,
            }}
            onMouseEnter={() => setHoveredTaskId(task.id)}
            onMouseLeave={() => setHoveredTaskId(null)}
            onClick={(e) => {
              const flatTasks = flattenTasksUtil(tasks);
              const flatTaskIds = flatTasks.map(t => t.id);
              const isMac = navigator.platform.toUpperCase().indexOf('MAC') >= 0;
              const ctrlOrCmd = isMac ? e.metaKey : e.ctrlKey;

              // Handle multi-selection
              handleSelectionClick(task.id, flatTaskIds, ctrlOrCmd, e.shiftKey);
              /* Pulsar tambien mueve el resaltado, asi que tambien se avisa:
                 quien siga la seleccion no debe tener que distinguir si vino
                 del raton o del teclado. */
              onTaskSelectionChange?.(task.id);

              // v1.9.6: Ctrl/Shift+click = solo selección — NO disparar onTaskClick
              // (el consumidor abre un drawer/modal ahí, lo que rompía la
              // multi-selección abriendo el detalle de cada tarea clickeada).
              if (!ctrlOrCmd && !e.shiftKey) {
                onTaskClick?.(task);
              }
            }}
            onDoubleClick={(e) => {
              // v0.8.0: Double-click event
              e.stopPropagation();
              onTaskDblClick?.(task);
            }}
            onContextMenu={(e) => {
              e.preventDefault();
              setContextMenu({
                isOpen: true,
                x: e.clientX,
                y: e.clientY,
                type: 'task',
                task,
              });

              // v0.8.0: Context menu event
              onTaskContextMenu?.(task, e);
            }}
            whileHover={{
              backgroundColor: v6
                ? (isSelected ? 'var(--v6-fila-seleccionada, rgba(15,163,146,0.08))' : 'var(--v6-fila-hover, rgba(14,17,20,0.025))')
                : (isSelected ? theme.accentLight : theme.hoverBg),
            }}
          >
            {/* v0.17.147: Drop indicator line ABOVE - clean horizontal line */}
            {showDropAbove && (
              <div
                style={{
                  position: 'absolute',
                  top: 0,
                  left: 0,
                  right: 0,
                  height: '2px',
                  backgroundColor: theme.accent,
                  zIndex: 10,
                }}
              />
            )}

            {/* v0.17.147: Drop indicator line BELOW - clean horizontal line */}
            {showDropBelow && (
              <div
                style={{
                  position: 'absolute',
                  bottom: 0,
                  left: 0,
                  right: 0,
                  height: '2px',
                  backgroundColor: theme.accent,
                  zIndex: 10,
                }}
              />
            )}

          {visibleColumns.map((column, colIndex) => {
            const isLastColumn = colIndex === visibleColumns.length - 1;
            const isNameColumn = column.id === 'name';

            // Drag-fill is available on assignees + date cells for non-parent tasks.
            const isParentRow = !!(task.subtasks && task.subtasks.length > 0);
            const fillColumn = (column.id === 'assignees' || column.id === 'startDate' || column.id === 'endDate')
              ? (column.id as 'assignees' | 'startDate' | 'endDate')
              : null;
            const canFill = !!fillColumn && !isParentRow;
            const showFillHandle = canFill && hoveredTaskId === task.id && !fillDrag;
            // Excel-style preview: highlight ONLY the cell of the column being
            // filled (not the whole row), on the rows covered by the drag.
            const cellInFill = inFillRange && !!fillDrag && fillDrag.column === column.id;

            return (
            <div
              key={`${task.id}-${column.id}`}
              role="gridcell"
              className={v6 ? 'flex items-center' : `px-4 flex items-center ${
                isNameColumn ? 'justify-start' : 'justify-center'
              }`}
              style={v6 ? {
                position: 'relative',
                width: isNameColumn ? undefined : `${column.width}px`,
                flex: isNameColumn ? '1 1 0' : '0 0 auto',
                minWidth: 0,
                height: '100%',
                alignItems: 'center',
                overflow: 'visible',
                backgroundColor: cellInFill ? `${theme.accent}22` : undefined,
              } : {
                position: 'relative', // for the fill handle
                // v0.17.129: All columns use fixed width for consistent resize behavior
                width: `${column.width}px`,
                minWidth: `${column.minWidth ?? (isNameColumn ? 200 : 60)}px`,
                maxWidth: `${column.maxWidth ?? 2000}px`,
                flexShrink: isNameColumn && visibleColumns.length === 1 ? 1 : 0,
                flexGrow: isNameColumn && visibleColumns.length === 1 ? 1 : 0,
                // v0.17.129: Consistent border handling - inline style like header
                borderRight: !isLastColumn ? `1px solid ${hoveredTaskId === task.id ? theme.border : theme.borderLight}` : 'none',
                height: '100%',
                boxSizing: 'border-box',
                overflow: 'visible',
                // Drag-fill preview on the target column's cells only.
                backgroundColor: cellInFill ? `${theme.accent}22` : undefined,
                boxShadow: cellInFill ? `inset 0 0 0 1px ${theme.accent}66` : undefined,
              }}
            >
              {renderCellContent(column, task, isNameColumn ? level : 0)}
              {showFillHandle && fillColumn && (
                <div
                  title="Arrastrá hacia abajo para aplicar a varias tareas"
                  onMouseDown={(e) => handleFillDragStart(e, task.id, fillColumn, index)}
                  style={{
                    position: 'absolute',
                    right: 2,
                    bottom: 2,
                    width: 8,
                    height: 8,
                    borderRadius: 2,
                    background: theme.accent,
                    border: `1px solid ${theme.bgPrimary}`,
                    cursor: 'crosshair',
                    zIndex: 5,
                  }}
                />
              )}
            </div>
          );
          })}
          </motion.div>
        );
      })}
      {/* R1 · lo que queda debajo de la franja, sin dibujar (la fila «añadir tarea» sigue al final) */}
      {filasVisibles && filasVisibles.hasta < flatTasks.length - 1 && <div aria-hidden data-relleno-abajo style={{ height: (flatTasks.length - 1 - filasVisibles.hasta) * ROW_HEIGHT }} />}
      {/* 1.9.45 · «+ Add task» en línea, al final (ESPEC pestañas §4.10). */}
      {addTaskRow && (
        <button
          type="button"
          data-anadir-tarea
          onClick={addTaskRow.onClick}
          className={v6 ? 'w-full flex items-center text-left' : 'w-full flex items-center gap-2 px-3 text-left text-[13px] transition-colors'}
          style={v6
            ? { height: 36, gap: 8, padding: '0 14px 0 34px', border: 0, background: 'transparent', color: 'var(--v6-tenue, #5F6972)', font: 'inherit', fontSize: 13, cursor: 'pointer' }
            : { height: `${ROW_HEIGHT}px`, color: theme.textTertiary, borderBottom: `1px solid ${theme.borderLight}` }}
          onMouseEnter={(e) => { e.currentTarget.style.color = v6 ? 'var(--v6-texto, #0E1114)' : theme.textPrimary; }}
          onMouseLeave={(e) => { e.currentTarget.style.color = v6 ? 'var(--v6-tenue, #5F6972)' : theme.textTertiary; }}
        >
          <Plus className="w-3.5 h-3.5" />
          {addTaskRow.label}
        </button>
      )}
      </div>

      {/* Context Menu */}
      <ContextMenu
        isOpen={contextMenu.isOpen}
        x={contextMenu.x}
        y={contextMenu.y}
        items={
          contextMenu.type === 'header' && contextMenu.columnId
            ? getHeaderContextMenuItems(contextMenu.columnId)
            : contextMenu.type === 'task' && contextMenu.task
            ? getTaskContextMenuItems(contextMenu.task)
            : []
        }
        onClose={() => setContextMenu({ ...contextMenu, isOpen: false })}
        theme={theme}
      />

      {/* v0.17.147: Ghost/Phantom drag preview - subtle horizontal line style */}
      {isDraggingState && ghostPosition && draggedTaskId && typeof document !== 'undefined' && createPortal(
        <div
          style={{
            position: 'fixed',
            left: ghostPosition.x + 12,
            top: ghostPosition.y - 10,
            zIndex: 99999,
            pointerEvents: 'none',
          }}
        >
          {/* Subtle ghost - just text with slight background */}
          {(() => {
            const draggedTask = flatTasks.find(ft => ft.task.id === draggedTaskId)?.task;
            return draggedTask ? (
              <div
                className="flex items-center gap-2 px-2 py-1 rounded"
                style={{
                  backgroundColor: 'rgba(255, 255, 255, 0.08)',
                  backdropFilter: 'blur(4px)',
                }}
              >
                <span
                  className="text-xs font-medium"
                  style={{
                    color: theme.textSecondary,
                    opacity: 0.9,
                  }}
                >
                  {draggedTask.name}
                </span>
              </div>
            ) : null;
          })()}
        </div>,
        document.body
      )}
    </div>
  );
}
